//! Everything in this file is asserted against bytes the shipped `ws` produced.
//!
//! `rust/fixtures/deflate-vectors.json` is generated by
//! `rust/scripts/gen-deflate-vectors.mjs`, which drives `ws`'s own
//! `PerMessageDeflate` through the same `extension.parse` -> `accept` ->
//! `extension.format` calls `websocket-server.js` makes, with the shipped
//! `WS_PER_MESSAGE_DEFLATE` options. The crate is therefore tested against the
//! peer it replaces, not against a reading of RFC 7692 -- which matters most
//! here, because `ws`'s choices are not the RFC's: it refuses parameters the RFC
//! says to ignore, it writes the server's own `no_context_takeover` flags into
//! the response regardless of the offer, and it honours a window the peer named
//! for us instead of ignoring it.
//!
//! Compression is cross-decoded rather than compared byte for byte: Node runs
//! zlib with `memLevel: 6`, this runs `zlib-rs` at `memLevel` 8 (`flate2` does
//! not expose the parameter), and two deflate implementations legitimately emit
//! different bytes for the same text. Negotiation IS compared byte for byte,
//! because the `Sec-WebSocket-Extensions` response is a string both sides act on.

use serde::Deserialize;
use std::collections::BTreeMap;

use pqp_deflate::{accept, encode_base64, Deflater, Inflater, Params};

const FIXTURE: &str = include_str!("../../../fixtures/deflate-vectors.json");

#[derive(Deserialize)]
struct Fixture {
    #[serde(rename = "wsVersion")]
    ws_version: String,
    #[serde(rename = "shippedPolicy")]
    shipped_policy: ShippedPolicy,
    vectors: Vec<Vector>,
    refusals: Vec<Refusal>,
}

/// Only the parts of the shipped option set this crate could act on. Recorded so
/// a change to `ws-compression.ts` shows up here as a number rather than as a
/// comment that still claims level 3.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ShippedPolicy {
    zlib_deflate_options: ZlibDeflateOptions,
    server_no_context_takeover: bool,
    client_no_context_takeover: bool,
    threshold: usize,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ZlibDeflateOptions {
    level: u8,
    mem_level: u8,
}

/// Field names here are this harness's, written snake_case by the generator. The
/// camelCase ones above it are copied verbatim out of the JS options object,
/// which is why they are renamed rather than restyled.
#[derive(Deserialize)]
struct Vector {
    name: String,
    /// `"server-sends"` when ws compressed as the server, `"client-sends"` when it
    /// compressed as a browser would. The crate sits in the server's seat, so the
    /// second kind is what its `Inflater` really has to read.
    direction: String,
    offer_header: String,
    response_header: String,
    accepted_params: BTreeMap<String, serde_json::Value>,
    frames: Vec<Frame>,
    /// The window `ws` compressed with -- our outbound direction, since the
    /// gateway stands in the same role.
    deflate_window_bits: u8,
    /// The window `ws` will decompress with -- our inbound direction must not
    /// exceed it.
    inflate_window_bits: u8,
    deflate_resets_each_message: bool,
    inflate_resets_each_message: bool,
}

#[derive(Deserialize)]
struct Frame {
    /// Base64 of the uncompressed payload.
    text: String,
    byte_length: usize,
    fin: bool,
    rsv1: bool,
    /// Absent (null) when `ws` sent the frame raw because it was under
    /// `threshold`.
    deflated: Option<String>,
}

#[derive(Deserialize)]
struct Refusal {
    name: String,
    offer_header: String,
    #[serde(default)]
    accepted: bool,
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE).expect("the deflate fixture parses")
}

fn decode(text: &str) -> Vec<u8> {
    pqp_deflate::decode_base64(text).expect("fixture base64 decodes")
}

/// Parameters built from the fixture's own recorded numbers, so a wrong
/// `accept()` cannot compensate for itself by feeding the stream its own
/// mistake.
fn params_from(v: &Vector) -> Params {
    Params {
        level: 3,
        client_max_window_bits: (v.inflate_window_bits != 15).then_some(v.inflate_window_bits),
        server_max_window_bits: (v.deflate_window_bits != 15).then_some(v.deflate_window_bits),
        client_no_context_takeover: v.inflate_resets_each_message,
        server_no_context_takeover: v.deflate_resets_each_message,
        ..Params::default()
    }
}

#[test]
fn the_fixture_is_the_version_of_ws_the_lockfile_pins() {
    let f = fixture();
    // A fixture produced by a different ws than the server runs is a fixture
    // about some other product. The lockfile is the authority, not the directory
    // the script happened to find.
    let lock = std::fs::read_to_string("../../../pnpm-lock.yaml").expect("lockfile readable");
    assert!(
        lock.contains(&format!("  ws@{}:", f.ws_version)),
        "fixture came from ws {} and pnpm-lock.yaml does not pin it",
        f.ws_version
    );
    assert_eq!(
        f.shipped_policy.zlib_deflate_options.level, 3,
        "shipped level"
    );
    assert_eq!(
        f.shipped_policy.zlib_deflate_options.mem_level, 6,
        "shipped memLevel"
    );
    // The two halves of one claim, asserted together: the shipped policy asks
    // for 6, this crate's default asks for 6, and 6 is what the backend is
    // actually opened with (`tests/memory.rs` measures the difference it makes).
    // While the stream went through `flate2` the third half was false and this
    // line asserted that, so a Rust gateway would have shipped the policy's
    // memory choice as a comment.
    assert_eq!(
        Params::default().mem_level,
        f.shipped_policy.zlib_deflate_options.mem_level,
        "the Rust default drifted from the shipped policy"
    );
    assert!(
        Params::default().mem_level_is_honoured(),
        "the shipped policy's memLevel is not reaching the backend: a socket costs \
         ~48 KiB more than the policy asked for, and docs/RUST.md's memory table is wrong"
    );
    assert!(f.shipped_policy.server_no_context_takeover);
    assert!(f.shipped_policy.client_no_context_takeover);
    assert!(
        f.shipped_policy.threshold > 0,
        "the threshold is what keeps a pong from becoming 17 bytes of deflate"
    );
}

/// A fixture that silently lost a case is worse than no fixture, because the
/// tests above would still pass. So the coverage itself is asserted, in terms of
/// what each case is FOR rather than how many there are: this is the test that
/// fails if someone regenerates the fixture and the 8-bit inbound frames, or the
/// fragmented message, or a sub-threshold raw frame, quietly disappear.
#[test]
fn the_fixture_still_contains_the_cases_it_claims() {
    let f = fixture();
    let has = |want: &str| f.vectors.iter().any(|v| v.direction == want);
    assert!(has("server-sends"), "no frames written by the server side");
    assert!(has("client-sends"), "no frames written by the client side");

    assert!(
        f.vectors.iter().any(|v| v.direction == "client-sends"
            && v.inflate_window_bits == 8
            && v.frames.iter().any(|fr| fr.rsv1)),
        "nothing compressed at an 8-bit window, so the clamp in Inflater::new is untested"
    );
    assert!(
        f.vectors.iter().any(|v| v.frames.iter().any(|fr| !fr.fin)),
        "no fragmented message, so the sync-marker-on-non-final-fragment rule is untested"
    );
    assert!(
        f.vectors
            .iter()
            .any(|v| v.frames.iter().any(|fr| !fr.rsv1 && fr.deflated.is_none())),
        "no sub-threshold raw frame, so the Sender's threshold decision is untested"
    );
    assert!(
        f.vectors
            .iter()
            .any(|v| v.response_header.contains("server_max_window_bits=")),
        "no response echoes a window the peer named, so honouring one is untested"
    );
    assert!(
        f.vectors.iter().any(|v| {
            v.frames.windows(2).any(|w| w[0].fin && w[1].fin)
                && v.deflate_resets_each_message
                && v.frames.iter().any(|fr| fr.rsv1)
        }),
        "no two whole messages on one connection, so no-context-takeover is untested"
    );
}

/// The response header is the byte-for-byte contract. Getting it wrong is not a
/// crash: a response that drops `server_no_context_takeover` is a connection that
/// works, keeps a deflate dictionary per socket, and quietly removes the memory
/// bound `ws-compression.ts` was written to install.
#[test]
fn the_negotiated_response_matches_what_ws_formats() {
    for v in &fixture().vectors {
        let accepted = accept(&v.offer_header)
            .unwrap_or_else(|e| panic!("{}: refused an offer ws accepted: {e}", v.name))
            .unwrap_or_else(|| panic!("{}: offer not recognised", v.name));
        assert_eq!(accepted.response, v.response_header, "{}", v.name);

        // Independent of the string: a parameter is in `ws`'s accepted parameters
        // exactly when it is in the response it formatted. Checking our
        // negotiation against both stops a mistake in one from cancelling out a
        // mistake in the other.
        for name in [
            "client_max_window_bits",
            "client_no_context_takeover",
            "server_max_window_bits",
            "server_no_context_takeover",
        ] {
            let in_params = v.accepted_params.contains_key(name);
            let in_response = accepted
                .response
                .split("; ")
                .any(|part| part == name || part.starts_with(&format!("{name}=")));
            assert_eq!(
                in_params, in_response,
                "{}: `{name}` in ws params {in_params}, in our response {in_response}",
                v.name
            );
        }

        assert_eq!(
            accepted.params.inbound_window_bits(),
            v.inflate_window_bits,
            "{} inbound window",
            v.name
        );
        assert_eq!(
            accepted.params.outbound_window_bits(),
            v.deflate_window_bits,
            "{} outbound window",
            v.name
        );
        assert_eq!(
            accepted.params.client_no_context_takeover, v.inflate_resets_each_message,
            "{}",
            v.name
        );
        assert_eq!(
            accepted.params.server_no_context_takeover, v.deflate_resets_each_message,
            "{}",
            v.name
        );
    }
}

/// Whatever `ws` compressed, this must inflate -- per message, in order, on one
/// stream per direction, at the negotiated window. This is the direction a
/// rolling deploy depends on: the Rust gateway reading frames a browser sent
/// through the Node server's framing.
#[test]
fn ws_compressed_frames_inflate_to_their_original_text() {
    for v in &fixture().vectors {
        let mut inflater = Inflater::new(&params_from(v));
        let mut seen = 0usize;
        for frame in &v.frames {
            let want = decode(&frame.text);
            assert_eq!(want.len(), frame.byte_length, "{}: fixture length", v.name);
            if !frame.rsv1 {
                // RSV1 clear means the payload is the message. Feeding it to the
                // inflater would corrupt the stream, because the stream was never
                // opened for it: that is why the flag is checked rather than the
                // presence of bytes.
                assert!(
                    frame.deflated.is_none(),
                    "{}: frame without RSV1 still carries deflate output",
                    v.name
                );
                continue;
            }
            let bytes = frame
                .deflated
                .as_deref()
                .unwrap_or_else(|| panic!("{}: RSV1 frame with no payload", v.name));
            let got = inflater
                .inflate(&decode(bytes), frame.fin)
                .unwrap_or_else(|e| panic!("{}: inflate failed: {e}", v.name));
            assert_eq!(got, want, "{}: frame {} mismatch", v.name, seen);
            seen += 1;
        }
        // Every frame is accounted for: each one either went through the
        // inflater or was asserted to be raw. A loop that silently skipped a
        // frame would otherwise still pass.
        assert_eq!(
            seen,
            v.frames.iter().filter(|frame| frame.rsv1).count(),
            "{}: not every RSV1 frame was inflated",
            v.name
        );
        assert!(
            seen >= 2,
            "{}: a vector with one compressed frame tests nothing about a stream",
            v.name
        );
    }
}

/// Every header `ws` refuses, this refuses too. The direction of the risk is
/// worth stating: refusing where `ws` accepts is a 400 and a client that cannot
/// connect, while accepting where `ws` refuses merely moves a disagreement onto
/// a working client. Both are asserted here rather than argued, and a refusal
/// `ws` does not actually implement is skipped rather than encoded as a rule.
#[test]
fn ws_refusals_are_refusals_here() {
    let mut refused = 0usize;
    for r in &fixture().refusals {
        let result = accept(&r.offer_header);
        if r.accepted {
            assert!(
                result.is_ok(),
                "{}: ws accepted {:?} and we refused: {result:?}",
                r.name,
                r.offer_header
            );
            continue;
        }
        refused += 1;
        assert!(
            result.is_err(),
            "{}: ws rejects {:?} and we accepted {result:?}",
            r.name,
            r.offer_header
        );
    }
    assert!(
        refused >= 5,
        "expected the fixture to carry refusals, got {refused}"
    );
}

/// The reverse leg: compress with this crate, hand the bytes to `ws` in
/// `rust/scripts/verify-rust-deflate.mjs`, and require Node to read them. Written
/// to `$PQP_RUST_DEFLATE_OUT` when set, mirroring `PQP_RUST_MINTED_OUT`.
#[test]
fn rust_output_is_written_for_node_to_read() {
    let Some(out) = std::env::var_os("PQP_RUST_DEFLATE_OUT") else {
        eprintln!("PQP_RUST_DEFLATE_OUT unset, skipping reverse leg");
        return;
    };
    let f = fixture();
    let mut vectors = Vec::new();
    for v in &f.vectors {
        let params = params_from(v);
        let mut deflater = Deflater::new(&params).expect("window is inside the backend's range");
        let mut frames = Vec::new();
        for frame in &v.frames {
            let payload = decode(&frame.text);
            // `ws` decides RSV1 in the Sender, not in compress(): under
            // no-context-takeover a frame below `threshold` goes out raw. The
            // recorded flag is reused rather than recomputed so both legs agree
            // on what the decision was.
            let compressed = if frame.rsv1 {
                Some(encode_base64(
                    &deflater
                        .deflate(&payload, frame.fin)
                        .unwrap_or_else(|e| panic!("{}: deflate failed: {e}", v.name)),
                ))
            } else {
                None
            };
            frames.push(serde_json::json!({
                "fin": frame.fin,
                "rsv1": frame.rsv1,
                "text": frame.text,
                "deflated": compressed,
            }));
        }
        vectors.push(serde_json::json!({
            "name": v.name,
            // Our own response header, so the verifier negotiates as a client
            // against what this crate answered rather than against ws's text.
            "response_header": accept(&v.offer_header)
                .unwrap()
                .expect("offer")
                .response,
            "deflate_window_bits": v.deflate_window_bits,
            "inflate_window_bits": v.inflate_window_bits,
            "frames": frames,
        }));
    }
    let doc = serde_json::json!({
        "generatedBy": "crates/pqp-deflate/tests/node_parity.rs",
        "note": "Deflate output of the Rust crate, for the Node harness to inflate. \
                 Synthetic frames; the base64 is compressed data, not credentials.",
        "wsVersionExpected": f.ws_version,
        "vectors": vectors,
    });
    std::fs::write(&out, serde_json::to_vec_pretty(&doc).expect("serialize")).expect("write");
}
